def LNK(a,b,i=0,t='main'):return (a,b,i,t)
STICKY_KEY="Set the values in the Config node (webhook key, Google Sheet ID, WhatsApp and Telegram details). The website sends the same key in the x-vaigai-key header. Credentials: Google Sheets OAuth2, Telegram, OpenAI (assistant only). Nodes marked optional are disabled until you add credentials."
# ---------- 1. AI assistant ----------
CFGN='Config'
w=webhook('Assistant Webhook',[0,300],'vaigai-assistant');cf=config([220,300]);k=keyif([440,300]);un=respond('Unauthorized',[660,520],'{"reply":"Unauthorized","actions":[],"quick_replies":[]}',401)
nm=code('Normalize Input',[660,300],CODE['normalize_input'])
ag=node('AI Agent','@n8n/n8n-nodes-langchain.agent',[900,300],{'promptType':'define','text':"={{ 'Customer language: ' + $json.lang + '\\nBasket: ' + JSON.stringify($json.basket) + '\\nPage context: ' + JSON.stringify($json.context) + '\\nRecent chat: ' + JSON.stringify($json.history) + '\\nCustomer message: ' + $json.message }}",'options':{'systemMessage':SYSTEM,'maxIterations':6,'returnIntermediateSteps':False}},1.7,onError='continueRegularOutput')
md=node('OpenAI Chat Model','@n8n/n8n-nodes-langchain.lmChatOpenAi',[820,560],{'model':{'__rl':True,'value':'gpt-4o-mini','mode':'list','cachedResultName':'gpt-4o-mini'},'options':{'temperature':0.3,'maxTokens':700}},1.2,{'openAiApi':{'id':'','name':'OpenAI account'}})
def tool(nm_,desc,key,pos):return node(nm_,'@n8n/n8n-nodes-langchain.toolCode',pos,{'name':nm_,'description':desc,'language':'javaScript','jsCode':CODE[key]},1.1)
tools=[tool('search_products','Find Vaigai products and exact prices. Input: plain text such as "ghee", "something for kids" or "curd for idli". Returns SKUs, names, units and prices. Always use this before stating a price.','tool_search',[1040,600]),
 tool('delivery_check','Check whether a Madurai area or 6-digit pincode is on the delivery route. Input: the area name or pincode as text. Always use before promising delivery.','tool_delivery',[1180,600]),
 tool('plan_calculator','Estimate the monthly cost of a daily or weekly plan. Input: JSON like {"sku":"VGM-CURD-400g","qty":1,"frequency":"daily"}. Use exact SKUs from search_products.','tool_plan',[1320,600]),
 tool('faq_lookup','Look up policies and quality answers (delivery time, pasteurisation, glass bottles, ordering, bulk). Input: the customer question as text.','tool_faq',[1460,600]),
 tool('store_info','Get opening hours, delivery promise, payment method and contact options. Input: any text.','tool_store',[1600,600])]
pr=code('Parse & Validate Reply',[1240,300],CODE['parse_reply'])
rs=respond('Respond to Website',[1480,220],"={{ JSON.stringify({reply:$json.reply,lang:$json.lang,actions:$json.actions,quick_replies:$json.quick_replies}) }}")
hf=ifnode('Handoff requested?',[1480,400],'={{ $json.handoff }}','boolean','true')
al=tg('Telegram: Handoff alert (optional)',[1720,400],"=Handoff requested\nSession: {{ $json.session_id }}\nCustomer said: {{ $json.message }}\nBot replied: {{ $json.reply }}")
lg=sheet('Log conversation (optional)',[1480,60],'Conversations','append',(['created_at','session_id','message','reply','lang','handoff'],'$json'),disabled=True)
nt=[note("AI ASSISTANT\n1. Add your OpenAI credential to 'OpenAI Chat Model' (or swap in an Anthropic / Gemini chat model node).\n2. "+STICKY_KEY+"\n3. Activate the workflow and copy the Production URL into the website: assistantWebhook.",[0,40],560,220),note("The agent only READS facts through tools and returns a validated JSON reply. Side effects (orders, leads) happen in the website and in workflows 02 and 04, so a prompt-injection can never place an order.",[900,40],520,140)]
nodes=[w,cf,k,un,nm,ag,md]+tools+[pr,rs,hf,al,lg]+nt
cn=[LNK(w['name'],cf['name']),LNK(cf['name'],k['name']),LNK(k['name'],nm['name'],0),LNK(k['name'],un['name'],1),LNK(nm['name'],ag['name']),LNK(ag['name'],pr['name']),LNK(pr['name'],rs['name']),LNK(pr['name'],hf['name']),LNK(pr['name'],lg['name']),LNK(hf['name'],al['name'],0),LNK(md['name'],ag['name'],0,'ai_languageModel')]+[LNK(t['name'],ag['name'],0,'ai_tool') for t in tools]
save('01-vaigai-ai-assistant.json',wf('Vaigai 01 · AI Assistant (agent)',nodes,cn))
# ---------- 2. Orders ----------
