nodes=[w,cf,k,un,vd,vi,bad,sv,ok,wc,wcu,wst,ts,n1,w2,cf2,k2,un2,rd,fo,rp]
cn=[LNK(w['name'],cf['name']),LNK(cf['name'],k['name']),LNK(k['name'],vd['name'],0),LNK(k['name'],un['name'],1),LNK(vd['name'],vi['name']),LNK(vi['name'],sv['name'],0),LNK(vi['name'],bad['name'],1),LNK(sv['name'],ok['name']),LNK(sv['name'],wc['name']),LNK(sv['name'],ts['name']),LNK(wc['name'],wcu['name'],0),LNK(wcu['name'],wst['name']),
 LNK(w2['name'],cf2['name']),LNK(cf2['name'],k2['name']),LNK(k2['name'],rd['name'],0),LNK(k2['name'],un2['name'],1),LNK(rd['name'],fo['name']),LNK(fo['name'],rp['name'])]
save('02-vaigai-orders.json',wf('Vaigai 02 · Orders and order status',nodes,cn))
