save('03-vaigai-daily-operations.json',wf('Vaigai 03 · Daily operations',[s1,c1,r1,pl,t1,ex,ar,s2,c2,r2,pd,t2,n3],[LNK(s1['name'],c1['name']),LNK(c1['name'],r1['name']),LNK(r1['name'],pl['name']),LNK(pl['name'],t1['name']),LNK(pl['name'],ex['name']),LNK(ex['name'],ar['name']),LNK(s2['name'],c2['name']),LNK(c2['name'],r2['name']),LNK(r2['name'],pd['name']),LNK(pd['name'],t2['name'])]))
